function flReadUrl(){const e=location.pathname.match(/^\/@?([^/]+)\/(followers|following)\/?$/);if(e)return{flUsername:decodeURIComponent(e[1]),flTab:e[2]};const l=new URLSearchParams(location.search);return{flUsername:l.get("u"),flTab:"following"===l.get("tab")?"following":"followers"}}let flUsername=null,flTab="followers",flProfile=null,flMyFollowing=new Set,flMyPending=new Set;function flRenderTabs(){document.getElementById("fl-tabs").innerHTML=`\n    <div class="xtabs">\n      <button class="xtab${"followers"===flTab?" active":""}" onclick="flSetTab('followers')">Followers</button>\n      <button class="xtab${"following"===flTab?" active":""}" onclick="flSetTab('following')">Following</button>\n    </div>`}function flSetTab(e){if(e!==flTab){flTab=e;try{history.replaceState(null,"",prettyFollowListUrl(flUsername,e))}catch(e){}flRenderTabs(),flLoadList()}}function flRowHtml(e,l){const n=e?.username||"unknown",o=currentSession&&e.id!==l,t=flMyFollowing.has(e.id),a=flMyPending.has(e.id);return`\n  <div class="fl-row">\n    <a class="ulrow" style="flex:1;min-width:0;" href="${profileUrl(n)}">\n      <img class="avatar pfp-md${avSqClass(e)}" src="${esc(avatarUrl(e?.avatar_url))}" alt="" loading="lazy" decoding="async">\n      <div class="ulrow-txt">\n        <span class="ulrow-name">${esc(e?.display_name||n)}${vBadge(e)}</span>\n        <span class="ulrow-handle">@${esc(n)}</span>\n      </div>\n    </a>\n    ${o?followBtnHtml(e,t,a):""}\n  </div>`}async function flLoadList(){const e=document.getElementById("followlist-root");if(!flProfile)return;e.innerHTML=skeletonFeedHtml(3);const l="followers"===flTab?"followee_id":"follower_id",n="followers"===flTab?"follower_id":"followee_id",{data:o,error:t}=await sb.from("follows").select(`${n}, profile:profiles!follows_${n}_fkey(id,username,display_name,avatar_url,verified,verification_type)`).eq(l,flProfile.id).order("created_at",{ascending:!1}).limit(200);if(t)return void(e.innerHTML=`<div class="errmsg">${esc(t.message)}</div>`);if(!o.length)return void(e.innerHTML=`<div class="empty-note">${"followers"===flTab?`@${esc(flProfile.username)} has no followers yet.`:`@${esc(flProfile.username)} isn't following anyone yet.`}</div>`);const a=currentSession?.user?.id||null;e.innerHTML=o.map(e=>flRowHtml(e.profile,a)).join("")}async function flToggleFollow(e,l){return genericToggleFollow(e,l)}async function flLoadMyFollowing(){flMyFollowing=new Set,flMyPending=new Set,await authReady;const e=currentSession;if(!e)return;const[{data:l},{data:n}]=await Promise.all([sb.from("follows").select("followee_id").eq("follower_id",e.user.id),sb.from("follow_requests").select("target_id").eq("requester_id",e.user.id)]);flMyFollowing=new Set((l||[]).map(e=>e.followee_id)),flMyPending=new Set((n||[]).map(e=>e.target_id))}async function loadFollowList(){if("followlist"!==document.body.dataset.page)return;const e=flReadUrl();flUsername=e.flUsername,flTab=e.flTab,flProfile=null,flMyFollowing=new Set;const l=document.getElementById("followlist-root");if(!l)return;if(!flUsername)return void(l.innerHTML='<div class="errmsg">No user specified.</div>');const{data:n,error:o}=await sb.from("profiles").select("*").ilike("username",flUsername).single();if(o||!n)return void(l.innerHTML='<div class="errmsg">No user found with that username.</div>');flProfile=n,document.title=`People followed by @${n.username} — InteractInk`,document.getElementById("fl-name").textContent=n.display_name||n.username,document.getElementById("fl-handle").textContent=`@${n.username}`,document.getElementById("fl-back").href=profileUrl(n.username);const t=prettyFollowListUrl(n.username,flTab);if(location.pathname!==t)try{history.replaceState(null,"",t)}catch(e){}setPageDescription(`People ${"following"===flTab?"followed by":"following"} @${n.username} on InteractInk.`),setCanonical(t),flRenderTabs(),await flLoadMyFollowing(),flLoadList()}document.addEventListener("DOMContentLoaded",loadFollowList);